package br.com.erp.pos;
import br.com.erp.auth.*;
import br.com.erp.shared.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;
@br.com.erp.shared.WorkflowAmounts @RestController @Validated @RequestMapping("/api/v1/commercial") @PreAuthorize("hasAuthority('commercial:read')")
public class CommercialController {
 private final com.fasterxml.jackson.databind.ObjectMapper json;private final JdbcTemplate db;private final BranchAccess access;private final WorkflowSupport flow;private final Audit audit;
 public CommercialController(JdbcTemplate db,BranchAccess access,WorkflowSupport flow,Audit audit,com.fasterxml.jackson.databind.ObjectMapper json){this.json=json;this.db=db;this.access=access;this.flow=flow;this.audit=audit;}
 private void snapshot(Actor a,UUID branch,String kind,UUID entity,Object input){try{db.update("INSERT INTO commercial_rule_history(id,tenant_id,branch_id,kind,entity_id,content,created_by) VALUES(?,?,?,?,?,?,?)",UUID.randomUUID(),a.tenantId(),branch,kind,entity,json.writeValueAsString(input),a.userId());}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}}
 public record Promotion(@NotNull UUID requestId,@NotNull UUID branchId,@NotNull UUID productId,@NotNull @Min(0) Long version,@NotNull @DecimalMin("0.01") @DecimalMax("99.99") @Digits(integer=2,fraction=2) BigDecimal percent,@NotNull LocalDate startsOn,@NotNull LocalDate endsOn,boolean active){}
 public record Seller(@NotNull UUID requestId,@NotNull UUID branchId,UUID id,@NotNull @Min(0) Long version,@NotBlank @Size(max=160) String name,@NotNull @DecimalMin("0") @DecimalMax("100") @Digits(integer=3,fraction=2) BigDecimal commissionPercent,boolean active){}
 public record Loyalty(@NotNull UUID requestId,@NotNull UUID branchId,@NotNull @Min(0) Long version,@NotNull @DecimalMin("0") @DecimalMax("1000") @Digits(integer=4,fraction=4) BigDecimal pointsPerReal,boolean active){}
 public record Redeem(@NotNull UUID requestId,@NotNull UUID branchId,@NotNull UUID customerId,@NotNull @DecimalMin("1") @Digits(integer=18,fraction=0) BigDecimal points,@NotBlank @Size(min=5,max=500) String note){}
 @GetMapping("/sale-options") @PreAuthorize("hasAuthority('pos:read')") @Transactional(readOnly=true) public Map<String,Object> options(@AuthenticationPrincipal Actor a,@RequestParam UUID branchId,@RequestParam(defaultValue="0") @Min(0) @Max(100000) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){access.requireBranch(a,branchId);return Map.of("items",db.queryForList("SELECT id,name FROM salesperson WHERE tenant_id=? AND branch_id=? AND active=TRUE ORDER BY name,id LIMIT ? OFFSET ?",a.tenantId(),branchId,size,(long)page*size),"total",db.queryForObject("SELECT COUNT(*) FROM salesperson WHERE tenant_id=? AND branch_id=? AND active=TRUE",Long.class,a.tenantId(),branchId),"page",page,"size",size);}
 @GetMapping("/{resource:promotions|sellers|ledger|history}") @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Map<String,Object> list(@AuthenticationPrincipal Actor a,@PathVariable String resource,@RequestParam UUID branchId,@RequestParam(defaultValue="0") @Min(0) @Max(100000) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){access.requireBranch(a,branchId);String table=resource.equals("promotions")?"commercial_promotion":resource.equals("sellers")?"salesperson":resource.equals("history")?"commercial_rule_history":"commercial_ledger",order=resource.equals("promotions")?"product_id":resource.equals("sellers")?"name,id":"created_at DESC,id";return Map.of("items",db.queryForList("SELECT * FROM "+table+" WHERE tenant_id=? AND branch_id=? ORDER BY "+order+" LIMIT ? OFFSET ?",a.tenantId(),branchId,size,(long)page*size),"total",db.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE tenant_id=? AND branch_id=?",Long.class,a.tenantId(),branchId),"page",page,"size",size);}
 @PutMapping("/promotions") @PreAuthorize("hasAuthority('commercial:read') and hasAuthority('commercial:write')") @Transactional public Map<String,Object> promotion(@AuthenticationPrincipal Actor a,@Valid @RequestBody Promotion p){flow.lock(a);access.requireBranch(a,p.branchId());String hash=flow.hash(p.branchId(),p.productId(),p.version(),p.percent(),p.startsOn(),p.endsOn(),p.active());if(flow.replay(a,p.requestId(),"PROMOTION",hash)!=null)return Map.of("productId",p.productId());if(p.endsOn().isBefore(p.startsOn())||p.startsOn().getYear()<1||p.endsOn().getYear()>9999)throw flow.bad("Período inválido.");if(db.queryForObject("SELECT COUNT(*) FROM product WHERE tenant_id=? AND id=? AND active=TRUE",Long.class,a.tenantId(),p.productId())!=1)throw flow.missing("Produto ativo não encontrado.");var rows=db.query("SELECT version FROM commercial_promotion WHERE tenant_id=? AND branch_id=? AND product_id=?",(r,i)->r.getLong(1),a.tenantId(),p.branchId(),p.productId());if((rows.isEmpty()?0:rows.getFirst())!=p.version().longValue())throw flow.conflict("Promoção alterada. Atualize.");if(rows.isEmpty())db.update("INSERT INTO commercial_promotion(tenant_id,branch_id,product_id,percent,starts_on,ends_on,active,version) VALUES(?,?,?,?,?,?,?,1)",a.tenantId(),p.branchId(),p.productId(),p.percent(),p.startsOn(),p.endsOn(),p.active());else db.update("UPDATE commercial_promotion SET percent=?,starts_on=?,ends_on=?,active=?,version=version+1 WHERE tenant_id=? AND branch_id=? AND product_id=?",p.percent(),p.startsOn(),p.endsOn(),p.active(),a.tenantId(),p.branchId(),p.productId());flow.record(a,p.requestId(),"PROMOTION",hash,p.productId());snapshot(a,p.branchId(),"PROMOTION",p.productId(),p);audit.record(a,"PROMOTION_CHANGED",p.productId());return Map.of("productId",p.productId());}
 @PutMapping("/sellers") @PreAuthorize("hasAuthority('commercial:read') and hasAuthority('commercial:write')") @Transactional public Map<String,Object> seller(@AuthenticationPrincipal Actor a,@Valid @RequestBody Seller s){flow.lock(a);access.requireBranch(a,s.branchId());String name=s.name().trim();if(name.isEmpty())throw flow.bad("Nome obrigatório.");String hash=flow.hash(s.branchId(),s.id(),s.version(),name,s.commissionPercent(),s.active());UUID replay=flow.replay(a,s.requestId(),"SELLER",hash);if(replay!=null)return Map.of("id",replay);UUID id=s.id()==null?UUID.randomUUID():s.id();if(s.id()==null){if(s.version()!=0)throw flow.conflict("Novo vendedor exige versão zero.");db.update("INSERT INTO salesperson(id,tenant_id,branch_id,name,commission_percent,active) VALUES(?,?,?,?,?,?)",id,a.tenantId(),s.branchId(),name,s.commissionPercent(),s.active());}else if(db.update("UPDATE salesperson SET name=?,commission_percent=?,active=?,version=version+1 WHERE tenant_id=? AND id=? AND branch_id=? AND version=?",name,s.commissionPercent(),s.active(),a.tenantId(),id,s.branchId(),s.version())!=1)throw flow.conflict("Vendedor alterado ou não encontrado.");flow.record(a,s.requestId(),"SELLER",hash,id);snapshot(a,s.branchId(),"SALESPERSON",id,s);audit.record(a,"SALESPERSON_CHANGED",id);return Map.of("id",id);}
 @GetMapping("/loyalty-policy") @Transactional(readOnly=true) public Map<String,Object> policy(@AuthenticationPrincipal Actor a,@RequestParam UUID branchId){access.requireBranch(a,branchId);var rows=db.queryForList("SELECT points_per_real,active,version FROM loyalty_policy WHERE tenant_id=? AND branch_id=?",a.tenantId(),branchId);return rows.isEmpty()?Map.of("points_per_real",BigDecimal.ZERO,"active",false,"version",0):rows.getFirst();}
 @PutMapping("/loyalty-policy") @PreAuthorize("hasAuthority('commercial:read') and hasAuthority('commercial:write')") @Transactional public Map<String,Object> loyalty(@AuthenticationPrincipal Actor a,@Valid @RequestBody Loyalty p){flow.lock(a);access.requireBranch(a,p.branchId());String hash=flow.hash(p.branchId(),p.version(),p.pointsPerReal(),p.active());if(flow.replay(a,p.requestId(),"LOYALTY_POLICY",hash)!=null)return policy(a,p.branchId());var rows=db.query("SELECT version FROM loyalty_policy WHERE tenant_id=? AND branch_id=?",(r,i)->r.getLong(1),a.tenantId(),p.branchId());if((rows.isEmpty()?0:rows.getFirst())!=p.version().longValue())throw flow.conflict("Política alterada.");if(rows.isEmpty())db.update("INSERT INTO loyalty_policy(tenant_id,branch_id,points_per_real,active,version) VALUES(?,?,?,?,1)",a.tenantId(),p.branchId(),p.pointsPerReal(),p.active());else db.update("UPDATE loyalty_policy SET points_per_real=?,active=?,version=version+1 WHERE tenant_id=? AND branch_id=?",p.pointsPerReal(),p.active(),a.tenantId(),p.branchId());flow.record(a,p.requestId(),"LOYALTY_POLICY",hash,p.branchId());snapshot(a,p.branchId(),"LOYALTY_POLICY",p.branchId(),p);audit.record(a,"LOYALTY_POLICY_CHANGED",p.branchId());return policy(a,p.branchId());}
 @GetMapping("/loyalty-balance") @PreAuthorize("hasAuthority('commercial:read') and hasAuthority('customer:read')") @Transactional(readOnly=true) public Map<String,Object> balance(@AuthenticationPrincipal Actor a,@RequestParam UUID branchId,@RequestParam UUID customerId){access.requireBranch(a,branchId);if(db.queryForObject("SELECT COUNT(*) FROM customer WHERE tenant_id=? AND id=?",Long.class,a.tenantId(),customerId)!=1)throw flow.missing("Cliente não encontrado.");return Map.of("points",db.queryForObject("SELECT COALESCE(SUM(points),0) FROM commercial_ledger WHERE tenant_id=? AND branch_id=? AND customer_id=?",BigDecimal.class,a.tenantId(),branchId,customerId));}
 @PostMapping("/redeem") @PreAuthorize("hasAuthority('commercial:read') and hasAuthority('commercial:write') and hasAuthority('customer:read')") @Transactional public Map<String,Object> redeem(@AuthenticationPrincipal Actor a,@Valid @RequestBody Redeem r){flow.lock(a);access.requireBranch(a,r.branchId());String note=r.note().trim();if(note.length()<5)throw flow.bad("Descreva o benefício entregue.");String hash=flow.hash(r.branchId(),r.customerId(),r.points(),note);if(flow.replay(a,r.requestId(),"LOYALTY_REDEEM",hash)!=null)return balance(a,r.branchId(),r.customerId());BigDecimal available=(BigDecimal)balance(a,r.branchId(),r.customerId()).get("points");if(r.points().compareTo(available)>0)throw flow.conflict("Saldo de pontos insuficiente.");db.update("INSERT INTO commercial_ledger(id,tenant_id,branch_id,customer_id,source_id,kind,commission,points,note,created_by) VALUES(?,?,?,?,?,'REDEEM',0,?,?,?)",UUID.randomUUID(),a.tenantId(),r.branchId(),r.customerId(),r.requestId(),r.points().negate(),note,a.userId());flow.record(a,r.requestId(),"LOYALTY_REDEEM",hash,r.customerId());audit.record(a,"LOYALTY_POINTS_REDEEMED",r.customerId());return balance(a,r.branchId(),r.customerId());}
}
